"""Native Route 4 trainers, encounters, gifts and legal level-25 progression."""
from pathlib import Path
source=Path(__file__).with_name('extract-pinwheel-data.py').read_text(encoding='utf8')
source=source.replace("'pinwheel-events.js'","'nimbasa-events.js'")
source=source.replace('[18,19,154,155]','[326]')
source=source.replace('for zone in [154,155]:','for zone in [326]:')
source=source.replace('changed=True\nwhile changed:',"obtainable|={row['id'] for row in json.loads((a.output/'castelia-data.js').read_text(encoding='utf8').split('=',1)[1].rstrip(';\\n'))['progression'].values() if row['obtainable']}\nchanged=True\nwhile changed:")
source=source.replace('if method and ((method==4 and param<=25)or method in [1,2,3]):','if method and ((method==4 and param<=25)or method in [1,2,3] or method==8 and param in [82,84,85]):')
source=source.replace('(619,93)]','(619,93),(403,75),(397,69),(355,27),(368,40)]')
source=source.replace('not in [154,155]','not in [326,327,328,90,62,65]')
source=source.replace("data={'source'", "ids|={2,158,450}|{c['args'][1] for p in programs.values() for c in p['code'].values() if c['name'] in ['WorkSet','WorkSetConst'] and c['args'][0]==32768 and 0<c['args'][1]<639}\ndata={'source'")
source=source.replace('619:249}','619:249,403:522,397:148,355:91,368:259}')
source=source.replace('assert species in names and form==0',"assert species in names and (form==0 or species==550 and form==1); native_personal=personal[struct.unpack_from('<H',personal[species],28)[0]+form-1] if form else personal[species]")
source=source.replace("'name':names[species]", "'name':'Basculin-Blue-Striped' if species==550 and form==1 else names[species]")
source=source.replace("'abilityId':personal[species][24]", "'abilityId':native_personal[25 if ga>>4==2 else 24]")
source=source.replace("if name==p['name']", "if name==p['name'] or sid==550 and p['name']=='Basculin-Blue-Striped'")
source=source.replace("items={};raw=", "mondata['Basculin-Blue-Striped']=dict(mondata['Basculin']);compat['Basculin-Blue-Striped']=list(compat['Basculin']);progression['Basculin-Blue-Striped']={**progression['Basculin'],'form':1,'dexName':'Basculin','abilities':list(personal[665][24:27]),'obtainable':False}\nitems={};raw=")
source=source.replace("(a.output/'pinwheel-data.js').write_text","(a.output/'nimbasa-data.js').write_text").replace('window.PINWHEEL_DATA=','window.NIMBASA_DATA=')
exec(compile(source,str(Path(__file__).with_name('extract-pinwheel-data.py')),'exec'))
